  targets_before?: {
    [k: string]: unknown;
  }[];
  targets_after?: {
    [k: string]: unknown;
  }[];
  type?: string | null;
  merge_direction?: string | null;
  snapshots?: {
    [k: string]: unknown;
  } | null;
